create or replace function public.list_admin_physical_items() returns table(item_type text,item_id text,status text,owner_full_name text,owner_id uuid,nfc_public_token uuid,nfc_path text,provisioned_at timestamptz,claimed_at timestamptz) language sql stable security definer set search_path='' as $$ select 'Treasure Box'::text,b.serial_code,case when b.claim_status='unclaimed' then 'Unclaimed' when b.setup_status='published' then 'Published' when b.setup_status is not null then initcap(replace(b.setup_status,'_',' ')) else initcap(replace(b.claim_status,'_',' ')) end,nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),b.owner_id,b.nfc_public_token,'/n/'||b.nfc_public_token::text,b.provisioned_at,b.claimed_at from public.physical_treasure_boxes b left join public.profiles p on p.id=b.owner_id union all select 'Traveling Token'::text,t.token_code,initcap(replace(t.status,'_',' ')),nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),t.owner_id,t.nfc_public_token,'/t/'||t.nfc_public_token::text,t.provisioned_at,t.activated_at from public.traveling_tokens t left join public.profiles p on p.id=t.owner_id order by provisioned_at desc nulls last; $$; revoke all on function public.list_admin_physical_items() from public; grant execute on function public.list_admin_physical_items() to authenticated;